import{_ as a,o as l,c as o,a3 as e}from"./chunks/framework.DdpBa4_E.js";const u=JSON.parse('{"title":"图片 alt 质量补全设计","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-11-21-image-alt-quality-design.md","filePath":"superpowers/specs/2026-11-21-image-alt-quality-design.md","lastUpdated":1795239163000}'),r={name:"superpowers/specs/2026-11-21-image-alt-quality-design.md"};function d(i,t,s,n,c,g){return l(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="图片-alt-质量补全设计" tabindex="-1">图片 alt 质量补全设计 <a class="header-anchor" href="#图片-alt-质量补全设计" aria-label="Permalink to &quot;图片 alt 质量补全设计&quot;">​</a></h1><blockquote><p>状态：已批准</p></blockquote><blockquote><p>日期：2026-11-21<br> 相关：README「待治理的内容问题」MD045；不触及掘金居中 HTML <code>&lt;img&gt;</code> 结构（另项暂缓）</p></blockquote><h2 id="_1-问题-非技术表述" tabindex="-1">1. 问题（非技术表述） <a class="header-anchor" href="#_1-问题-非技术表述" aria-label="Permalink to &quot;1. 问题（非技术表述）&quot;">​</a></h2><p>站点里绝大多数图<strong>能正常显示</strong>。缺的是图的「文字说明」（Markdown 里的 alt）：读屏软件读到空说明时，只能说「图片」，听不出图里是什么。</p><p>这不是丢图，主要是 EPUB / 掘金等书源迁移时原稿就没写说明，导入脚本原样保留了空 alt。</p><p>规模（2026-11-21 扫描）：约 <strong>1617</strong> 处空 alt / <strong>436</strong> 文件；本地图路径均可解析到文件；约 619 处为外链图。</p><h2 id="_2-目标与成功标准" tabindex="-1">2. 目标与成功标准 <a class="header-anchor" href="#_2-目标与成功标准" aria-label="Permalink to &quot;2. 目标与成功标准&quot;">​</a></h2><p><strong>目标：</strong> 质量优先，给读者（尤其读屏）可用的短中文说明；普通视觉阅读几乎无感。</p><p><strong>成功标准：</strong></p><ul><li>处理过的书：<code>![](</code> 空 alt 清零；图仍能显示；抽检说明与图意相符。</li><li>先试点 3 本定 SOP，再按 SOP 分批全站；不以「一次全自动灌假 alt」交差。</li><li>SOP 跑通并抽检合格前：<strong>不</strong>全站启用 markdownlint MD045（避免历史债堵 CI）。</li><li>全站扫完后再评估：启用 MD045、更新 README TODO 计数与状态。</li></ul><h2 id="_3-非目标-本阶段不做" tabindex="-1">3. 非目标（本阶段不做） <a class="header-anchor" href="#_3-非目标-本阶段不做" aria-label="Permalink to &quot;3. 非目标（本阶段不做）&quot;">​</a></h2><ul><li>不治理掘金源 <code>&lt;p align=center&gt;&lt;img&gt;</code> 居中 HTML（README 已记暂缓）。</li><li>不批量用文件名（如 <code>image-002</code>）冒充语义 alt。</li><li>不改图片文件本身、不改版式、不换图源（除非原链接已失效且另立项）。</li><li>不把「上下文启发式自动填」当作最终质量标准（仅可作草稿辅助）。</li></ul><h2 id="_4-策略" tabindex="-1">4. 策略 <a class="header-anchor" href="#_4-策略" aria-label="Permalink to &quot;4. 策略&quot;">​</a></h2><p><strong>试点精修 → 沉淀 SOP → 分批全站。</strong></p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th></tr></thead><tbody><tr><td>P0 试点</td><td>精修 3 本不同类型，验证写说明的质量条与工作量</td></tr><tr><td>P1 SOP</td><td>把检查清单、文案约定、验收命令写成可复用流程</td></tr><tr><td>P2 分批</td><td>按空 alt 数量从少到多处理其余书；每书一 PR</td></tr><tr><td>P3 收尾</td><td>全站清零后评估开 MD045；更新 README / lint 配置</td></tr></tbody></table><h2 id="_5-试点书目" tabindex="-1">5. 试点书目 <a class="header-anchor" href="#_5-试点书目" aria-label="Permalink to &quot;5. 试点书目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>slug</th><th>书名倾向</th><th>约空 alt</th><th>覆盖类型</th></tr></thead><tbody><tr><td><code>typescript-intro</code></td><td>TypeScript 入门教程</td><td>~21</td><td>技术小册，体量小，适合首本</td></tr><tr><td><code>docker-guide</code></td><td>Docker 实践指南</td><td>~54</td><td>掘金类外链图 + 「如下图」上下文多</td></tr><tr><td><code>attached</code></td><td>关系的重建</td><td>~40</td><td>EPUB 本地 <code>_assets</code> 插图</td></tr></tbody></table><p>大户（如 <code>yan-tie-lun</code> ~442、<code>claude-code-dev</code> ~161）放在 SOP 稳定后处理。</p><h2 id="_6-单图质量条-写-alt-时遵守" tabindex="-1">6. 单图质量条（写 alt 时遵守） <a class="header-anchor" href="#_6-单图质量条-写-alt-时遵守" aria-label="Permalink to &quot;6. 单图质量条（写 alt 时遵守）&quot;">​</a></h2><ol><li><strong>看图 + 看前后文</strong>，写一句中文，约 <strong>8–30 字</strong>，说明图传达的信息（图表主题、截图界面、示意图关系等）。</li><li><strong>装饰图</strong>（重复花边、无信息内容、同一装饰资源反复出现）：统一用约定文案 <strong><code>装饰图</code></strong>，不强行编造情节。</li><li><strong>禁止</strong>：空 alt；纯文件名；与图无关的套话；把整段正文复制进 alt。</li><li><strong>外链图</strong>：只补 alt，不改为本地（除非链接失效另案处理）。</li><li><strong>语法</strong>：在空的方括号里填上说明文字，圆括号里的路径保持原样不动。</li></ol><h2 id="_7-sop-大纲-p1-落成独立文档" tabindex="-1">7. SOP 大纲（P1 落成独立文档） <a class="header-anchor" href="#_7-sop-大纲-p1-落成独立文档" aria-label="Permalink to &quot;7. SOP 大纲（P1 落成独立文档）&quot;">​</a></h2><p>试点通过后，写成例如 <code>docs/superpowers/specs/image-alt-sop.md</code>（或 <code>docs/</code> 下维护文档），至少包含：</p><ol><li><strong>列清单</strong>：对该 slug 扫出所有 <code>![](</code>。</li><li><strong>逐张补全</strong>：打开图（本地文件或外链）+ 上下文，按质量条写 alt。</li><li><strong>装饰图规则</strong>：套用「装饰图」约定。</li><li><strong>自检</strong>： <ul><li><code>rg &#39;!\\[\\]\\(&#39; docs/books/&lt;slug&gt;</code> 无命中；</li><li>抽若干章节确认图仍显示、说明合理；</li><li>不引入 markdownlint 格式债（必要时 <code>npm run lint:fix</code> 仅限改动文件）。</li></ul></li><li><strong>提交</strong>：分支 <code>docs/alt-&lt;slug&gt;</code>；提交说明 <code>docs: 补全《书名》图片 alt（slug）</code>；开 PR。</li><li><strong>进度</strong>：维护一张「已完成 slug」列表（可放在 SOP 文末），避免重复劳动。</li></ol><h2 id="_8-工具与自动化边界" tabindex="-1">8. 工具与自动化边界 <a class="header-anchor" href="#_8-工具与自动化边界" aria-label="Permalink to &quot;8. 工具与自动化边界&quot;">​</a></h2><ul><li><strong>允许</strong>：脚本生成「待办清单」（文件:行号:路径）；<code>--dry-run</code> 统计；可选「上下文草稿」供人工改。</li><li><strong>不允许</strong>：无审阅的全站自动写回；用文件名批量填 alt 后宣称完成。</li><li>试点阶段以 Agent 看图（Read 本地图 / 打开外链上下文）+ 人工抽检为主；SOP 稳定后再考虑轻量辅助脚本。</li></ul><h2 id="_9-对读者体验的影响" tabindex="-1">9. 对读者体验的影响 <a class="header-anchor" href="#_9-对读者体验的影响" aria-label="Permalink to &quot;9. 对读者体验的影响&quot;">​</a></h2><ul><li><strong>视觉</strong>：几乎不变（只改 Markdown alt 文本）。</li><li><strong>读屏</strong>：说明从无到有，体验变好。</li><li><strong>风险</strong>：写错 alt 会误导读屏用户 → 靠质量条与抽检控制；发现错误按书热修。</li></ul><h2 id="_10-验收-每个-pr" tabindex="-1">10. 验收（每个 PR） <a class="header-anchor" href="#_10-验收-每个-pr" aria-label="Permalink to &quot;10. 验收（每个 PR）&quot;">​</a></h2><ul><li>[ ] 该书空 alt 为 0</li><li>[ ] 抽检 ≥3 张：说明与图意一致（或确认为「装饰图」）</li><li>[ ] 未改无关书籍；路径未被改坏</li><li>[ ] PR 说明含 slug 与处理数量</li></ul><h2 id="_11-开放问题-审阅时确认" tabindex="-1">11. 开放问题（审阅时确认） <a class="header-anchor" href="#_11-开放问题-审阅时确认" aria-label="Permalink to &quot;11. 开放问题（审阅时确认）&quot;">​</a></h2><p>无阻塞项。已确认：质量优先、全站分批、先试点三本再 SOP。</p>',32)])])}const p=a(r,[["render",d]]);export{u as __pageData,p as default};
